    login: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "email": "mireille@mamboproxi.com",
                 *       "password": "••••••••••••",
                 *       "rememberMe": true
                 *     }
                 */
                "application/json": components["schemas"]["LoginInput"];
            };
        };
        responses: {
            /** @description Connecté. Cookies `mp_at`, `mp_rt` et `mp_csrf` déposés. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "status": "AUTHENTICATED",
                     *       "user": {
                     *         "id": "clx8m2k4p0001mp9a7v3f2c1d",
                     *         "email": "mireille@mamboproxi.com",
                     *         "name": "Mireille Bell",
                     *         "firstName": "Mireille",
                     *         "initials": "MB",
                     *         "role": "ADMIN",
                     *         "lastLoginAt": "2026-10-19T07:58:00.000Z"
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["LoginResult"];
                };
            };
            /** @description Code de vérification envoyé par e-mail. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "status": "OTP_REQUIRED",
                     *       "challengeId": "clx8m9q2r0004mp9ahd8s7k2x",
                     *       "emailHint": "m•••••@mamboproxi.com",
                     *       "resendAvailableAt": "2026-10-20T09:42:12.000Z"
                     *     }
                     */
                    "application/json": components["schemas"]["LoginResult"];
                };
            };
            /** @description Identifiants incorrects. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "https://api.mamboproxi.com/problems/invalid-credentials",
                     *       "title": "Identifiants incorrects",
                     *       "status": 401,
                     *       "detail": "L'adresse e-mail ou le mot de passe est incorrect."
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Compte temporairement verrouillé. */
            423: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "https://api.mamboproxi.com/problems/account-locked",
                     *       "title": "Compte verrouillé",
                     *       "status": 423,
                     *       "detail": "Trop de tentatives. Réessayez dans 15 minutes ou réinitialisez votre mot de passe."
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["TooManyRequests"];
        };
    };
